import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Several agents on one repository","description":"How Wake keeps several coding agents on one repository from building the same task: claims, refusals, renewals, stale claims and evidence.","frontmatter":{"description":"How Wake keeps several coding agents on one repository from building the same task: claims, refusals, renewals, stale claims and evidence."},"headers":[],"relativePath":"agents/several-agents.md","filePath":"agents/several-agents.md","lastUpdated":1794487513000}'),n={name:"agents/several-agents.md"};function i(r,e,h,l,c,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="several-agents-on-one-repository" tabindex="-1">Several agents on one repository <a class="header-anchor" href="#several-agents-on-one-repository" aria-label="Permalink to &quot;Several agents on one repository&quot;">​</a></h1><p>Two agents on one repository can pick the same task and build it twice, or overwrite each other&#39;s work. Wake prevents that with claims: each session says which task it works on, and the others leave that task alone. Your agents follow these rules through the <code>wake</code> skill that <code>wake connect</code> installs; you don&#39;t run anything yourself.</p><h2 id="each-session-starts-with-the-free-tasks" tabindex="-1">Each session starts with the free tasks <a class="header-anchor" href="#each-session-starts-with-the-free-tasks" aria-label="Permalink to &quot;Each session starts with the free tasks&quot;">​</a></h2><p>A <a href="/wake-dist/docs/start/concepts#session">session</a> is one run of a coding agent. When it starts, Wake syncs the plan and tells the agent which tasks are free and which ones other sessions hold. The agent treats the held ones as off limits, even when your request touches them: it says so and asks you how to proceed.</p><h2 id="a-claim-before-any-work" tabindex="-1">A claim before any work <a class="header-anchor" href="#a-claim-before-any-work" aria-label="Permalink to &quot;A claim before any work&quot;">​</a></h2><p>The agent <a href="/wake-dist/docs/start/concepts#claim">claims</a> a task before it works on it, and starts only after the claim succeeds. While the claim is active, only the session that holds it can change the task.</p><h2 id="a-second-agent-is-refused" tabindex="-1">A second agent is refused <a class="header-anchor" href="#a-second-agent-is-refused" aria-label="Permalink to &quot;A second agent is refused&quot;">​</a></h2><p>When another session tries to claim a task that is already held, Wake refuses it with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Another holder is working on this task; pick another one</span></span></code></pre></div><p>That agent never works on the task: it picks another task and tells you which one.</p><h2 id="claims-are-renewed-while-the-agent-works" tabindex="-1">Claims are renewed while the agent works <a class="header-anchor" href="#claims-are-renewed-while-the-agent-works" aria-label="Permalink to &quot;Claims are renewed while the agent works&quot;">​</a></h2><p>A claim lasts 5 minutes unless the agent asks for longer, up to an hour, and the agent renews it every few minutes while it works. An agent that stops working on a task without finishing it releases the claim, so another session can take it.</p><h2 id="a-stale-claim-waits-for-you" tabindex="-1">A stale claim waits for you <a class="header-anchor" href="#a-stale-claim-waits-for-you" aria-label="Permalink to &quot;A stale claim waits for you&quot;">​</a></h2><p>A claim whose holder stopped renewing it is stale. Another session takes that task over only after you confirm: its agent asks you first.</p><h2 id="ending-a-session-releases-its-claims" tabindex="-1">Ending a session releases its claims <a class="header-anchor" href="#ending-a-session-releases-its-claims" aria-label="Permalink to &quot;Ending a session releases its claims&quot;">​</a></h2><p>When a session ends, Wake releases the claims it still holds, and the tasks are free again for the next session.</p><h2 id="evidence-before-a-task-is-done" tabindex="-1">Evidence before a task is done <a class="header-anchor" href="#evidence-before-a-task-is-done" aria-label="Permalink to &quot;Evidence before a task is done&quot;">​</a></h2><p>The agent attaches <a href="/wake-dist/docs/start/concepts#evidence">evidence</a> before it completes a task: test output, screenshots, logs, a link or a short note. Wake refuses to complete a task without evidence unless the agent states why none is possible, and records that reason with the task.</p>',18)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
